package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class OperatorDiagnosticsAcceptance {
 static final String API="/api/openservice/diagnostics";
 static Map<String,Object> result(java.net.http.HttpResponse<byte[]> r)throws Exception{return TransferAcceptance.result(r,200);}
 static void run(WorkflowSupport h)throws Exception{
  h.account("DiagnosticReader","reader");h.account("DiagnosticAdmin","admin");String secret="SENTINEL_"+id().substring(0,16),job=WorkFailureAlertsAcceptance.breakJob(h.store,secret);String migration=MigrationRowsAcceptance.seed(h.store);long events;
  try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);db.update("UPDATE os_work SET kind=?,state='failed' WHERE job_id=?",secret,job);String record=PlatformFoundationTest.record(db,"incident",secret);db.update("INSERT INTO os_attachment(sys_id,record_id,name,content,quarantined,hold_revision) VALUES(?,?,?,?,1,0)",id(),record,secret,secret.getBytes());events=db.count("SELECT COUNT(*) FROM os_security_event");db.connection.commit();}
  var response=h.get(API,auth("admin"));var data=result(response);assertEquals("openservice-diagnostics-v1",data.get("format"));assertEquals(true,object(data.get("database")).get("schema_matches"));assertEquals(1,((Number)object(data.get("queue")).get("failed")).intValue());assertEquals(1,((Number)object(data.get("attachments")).get("untracked")).intValue());assertEquals(1,((Number)object(data.get("attachments")).get("held")).intValue());assertEquals(1,((Number)object(data.get("migrations")).get("fetching")).intValue());assertFalse(object(data.get("queue")).containsKey("counts"));assertFalse(html(response).contains(secret));assertFalse(html(response).contains(job));assertFalse(html(response).contains(migration));assertFalse(html(response).contains("DiagnosticReader"));assertFalse(object(data.get("preflight")).get("shared_release_qualified").equals(true));assertEquals("no-store",response.headers().firstValue("cache-control").orElseThrow());
  var exported=h.get("/admin/diagnostics/export",auth("admin"));assertEquals(200,exported.statusCode());assertTrue(exported.headers().firstValue("content-disposition").orElseThrow().contains("openservice-diagnostics.json"));assertEquals("openservice-diagnostics-v1",parsed(exported).get("format"));assertFalse(html(exported).contains(secret));
  assertEquals(401,h.get(API,null).statusCode());for(String path:List.of(API,"/admin/diagnostics","/admin/diagnostics/export")){assertEquals(403,h.get(path,auth("DiagnosticReader")).statusCode());assertEquals(path.startsWith("/api/")?405:403,h.json("POST",path,map(),auth("admin")).statusCode());if(!path.startsWith("/api/"))assertEquals(405,h.protectedForm(path,map(),auth("admin")).statusCode());assertEquals(400,h.get(path+"?include=secrets",auth("admin")).statusCode());}try(var db=h.store.open()){db.update("UPDATE os_user SET role='reader' WHERE name='DiagnosticAdmin'");db.connection.commit();}assertEquals(403,h.get(API,auth("DiagnosticAdmin")).statusCode());
  var env=new org.springframework.mock.env.MockEnvironment();env.merge((org.springframework.core.env.ConfigurableEnvironment)h.environment);for(String key:List.of("WORK_ENABLED","ATTACHMENT_SCANNING_ENABLED","AI_ENABLED","AI_SUPPORT_ENABLED"))env.setProperty(key,"true");env.setProperty("ARBITRARY_SECRET",secret);var enabled=new Store(env);try(var db=enabled.open()){PlatformFoundationTest.bind(db);var snapshot=OperatorDiagnostics.inspect(enabled,db);for(Object flag:object(snapshot.get("flags")).values())assertEquals(true,flag);assertFalse(JSON.writeValueAsString(snapshot).contains(secret));db.update("DELETE FROM os_migration WHERE version=?",Migrations.VERSION);assertEquals(false,object(OperatorDiagnostics.inspect(enabled,db).get("database")).get("schema_matches"));db.connection.rollback();assertEquals(events,db.count("SELECT COUNT(*) FROM os_security_event"));}
 }
}
